// Extract Due Diligence tasks and prepare for database
const tasks = $input.first().json.result || [];
console.log(`Found ${tasks.length} total tasks`);

const dueDiligenceTasks = [];

for (const task of tasks) {
  const title = task.title ? task.title.toString().trim() : '';
  const description = task.description ? task.description.toString().trim() : '';

  // Check if title contains "Due Diligence" (case insensitive)
  const titleLower = title.toLowerCase();
  if (titleLower.includes('due diligence')) {
    let companyName = '';

    // Extract company name from title
    const colonPattern = /due diligence:\s*(.+)/i;
    const colonMatch = title.match(colonPattern);
    if (colonMatch) {
      companyName = colonMatch[1].trim().replace(/^["']+|["']+$/g, '');
    } else {
      const afterDD = title.substring(title.toLowerCase().indexOf('due diligence') + 13).trim();
      companyName = afterDD.replace(/^[:\s"']+/, '').replace(/["']+$/, '').trim() || 'Unknown Company';
    }

    // Extract website from description
    const urlRegex = /https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)/g;
    const urls = description.match(urlRegex) || [];
    const website = urls.length > 0 ? urls[0] : '';

    console.log(`✅ Found Due Diligence task: "${companyName}" (ID: ${task.id})`);

    dueDiligenceTasks.push({
      json: {
        kanboard_task_id: task.id,
        title: title,
        company_name: companyName,
        website: website,
        description: description,
        project_id: task.project_id || 1,
        status: 'pending',
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      }
    });
  }
}

if (dueDiligenceTasks.length === 0) {
  console.log('ℹ️ No Due Diligence tasks found');
  return [{ json: { message: 'No Due Diligence tasks found' } }];
}

console.log(`📋 Processing ${dueDiligenceTasks.length} Due Diligence tasks`);
return dueDiligenceTasks;

// Process attachments and extract text content
const taskData = $('Extract DD Tasks').first().json;
const attachmentsResponse = $input.first().json;

console.log(`📎 Processing attachments for task ${taskData.kanboard_task_id}`);

// Handle different response structures
let attachments = [];
if (attachmentsResponse && attachmentsResponse.result) {
  attachments = Array.isArray(attachmentsResponse.result) ? attachmentsResponse.result : [];
} else if (Array.isArray(attachmentsResponse)) {
  attachments = attachmentsResponse;
}

// Create attachment information summary
let attachmentInfo = '';
if (attachments.length > 0) {
  attachmentInfo = 'ATTACHMENTS FOUND:\n';
  attachments.forEach((file, index) => {
    const fileName = file.name || file.filename || `Document ${index + 1}`;
    const fileSize = file.size ? ` (${Math.round(file.size / 1024)} KB)` : '';
    const fileType = fileName.toLowerCase().includes('.pdf') ? 'PDF' : 
                     fileName.toLowerCase().includes('.doc') ? 'Word Document' : 
                     fileName.toLowerCase().includes('.xls') ? 'Excel Spreadsheet' : 'Document';

    attachmentInfo += `- ${fileType}: ${fileName}${fileSize}\n`;
  });
} else {
  attachmentInfo = 'No attachments found.';
}

console.log(`📎 Attachment summary: ${attachments.length} files`);

return [{
  json: {
    ...taskData,
    attachment_count: attachments.length,
    attachment_info: attachmentInfo,
    attachments: attachments
  }
}];

// Check which sections are missing for each report
const reports = $input.all();
const sectionsToGenerate = [];

// Define all 20 due diligence sections (Your Specific Requirements)
const ddSections = [
  'introduction_engagement_context',
  'methodology_reliability_levels',
  'company_overview',
  'business_model_unit_economics',
  'products_technology',
  'target_market_competitive_set',
  'financials_multi_year',
  'cash_burn_runway',
  'revenue_quality_client_cohorts',
  'partnerships_ecosystem',
  'intellectual_property',
  'legal_regulatory',
  'governance_board_effectiveness',
  'capital_structure_dilution',
  'risk_matrix_mitigations',
  'gaps_uncertainties_disclaimers',
  'scenario_analysis',
  'strategic_options',
  'recommendations_next_steps',
  'source_map_integrity_log'
];

for (const report of reports) {
  const reportJson = report.json;

  for (const section of ddSections) {
    // Check if section is null or empty
    if (!reportJson[section] || reportJson[section].trim() === '') {
      sectionsToGenerate.push({
        json: {
          id: reportJson.id,
          kanboard_task_id: reportJson.kanboard_task_id,
          company_name: reportJson.company_name,
          website: reportJson.website,
          description: reportJson.description,
          attachment_info: reportJson.attachment_info,
          section_name: section,
          section_title: section.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
          existing_sections: ddSections.filter(s => reportJson[s] && reportJson[s].trim() !== '').join(', ')
        }
      });
      break; // Generate one section at a time
    }
  }
}

console.log(`📊 Found ${sectionsToGenerate.length} sections to generate`);

if (sectionsToGenerate.length === 0) {
  return [{ json: { message: 'All reports complete' } }];
}

return sectionsToGenerate;

// Generate AI prompt for the specific section
const sectionData = $input.first().json;

if (sectionData.message) {
  return [{ json: sectionData }]; // Pass through completion message
}

const prompt = `You are an expert financial analyst conducting due diligence on ${sectionData.company_name}.

COMPANY INFORMATION:
- Name: ${sectionData.company_name}
- Website: ${sectionData.website || 'Not provided'}
- Description: ${sectionData.description || 'Not provided'}
- Attachments: ${sectionData.attachment_info || 'None'}

PREVIOUSLY COMPLETED SECTIONS:
${sectionData.existing_sections || 'None yet'}

TASK: Generate the "${sectionData.section_title}" section for this due diligence report.

REQUIREMENTS:
- Be specific and factual
- Use real information when possible
- Minimum 300 words
- Professional analysis format
- Include key metrics and insights
- Reference the company's actual business model and industry

Generate ONLY the content for the "${sectionData.section_title}" section:`;

console.log(`🤖 Generating prompt for ${sectionData.section_title} section`);

return [{
  json: {
    ...sectionData,
    ai_prompt: prompt
  }
}];

// Process AI response and prepare for database update
const sectionData = $('Create Section Prompt').first().json;
const aiResponse = $input.first().json;

if (sectionData.message) {
  return [{ json: sectionData }]; // Pass through completion message
}

const generatedContent = aiResponse.response || '';
const cleanContent = generatedContent
  .replace(/\{\{[^}]*\}\}/g, 'information not available')
  .replace(/\$json\.[\w.]+/g, 'information not available')
  .trim();

console.log(`📝 Generated ${sectionData.section_title}: ${cleanContent.substring(0, 100)}...`);

return [{
  json: {
    id: sectionData.id,
    section_name: sectionData.section_name,
    section_content: cleanContent,
    updated_at: new Date().toISOString()
  }
}];

// Generate PDF content from all sections
const reports = $input.all();
const pdfReports = [];

for (const report of reports) {
  const data = report.json;

  // Check if all sections are complete
  const sections = [
    'introduction_engagement_context', 'methodology_reliability_levels', 'company_overview', 'business_model_unit_economics',
    'products_technology', 'target_market_competitive_set', 'financials_multi_year', 'cash_burn_runway',
    'revenue_quality_client_cohorts', 'partnerships_ecosystem', 'intellectual_property', 'legal_regulatory',
    'governance_board_effectiveness', 'capital_structure_dilution', 'risk_matrix_mitigations', 'gaps_uncertainties_disclaimers',
    'scenario_analysis', 'strategic_options', 'recommendations_next_steps', 'source_map_integrity_log'
  ];

  const allComplete = sections.every(section => data[section] && data[section].trim() !== '');

  if (allComplete) {
    // Generate PDF content
    const pdfContent = `# Due Diligence Report: ${data.company_name}

` +
      `**Generated:** ${new Date().toLocaleDateString()}\n` +
      `**Website:** ${data.website || 'Not provided'}\n\n` +
      `## 1. Introduction & Engagement Context\n${data.introduction_engagement_context}\n\n` +
      `## 2. Methodology & Reliability Levels\n${data.methodology_reliability_levels}\n\n` +
      `## 3. Company Overview\n${data.company_overview}\n\n` +
      `## 4. Business Model & Unit Economics\n${data.business_model_unit_economics}\n\n` +
      `## 5. Products & Technology\n${data.products_technology}\n\n` +
      `## 6. Target Market & Competitive Set\n${data.target_market_competitive_set}\n\n` +
      `## 7. Financials (Multi-Year, reconciled & recomputed)\n${data.financials_multi_year}\n\n` +
      `## 8. Cash, Burn, Runway\n${data.cash_burn_runway}\n\n` +
      `## 9. Revenue Quality & Client Cohorts\n${data.revenue_quality_client_cohorts}\n\n` +
      `## 10. Partnerships & Ecosystem\n${data.partnerships_ecosystem}\n\n` +
      `## 11. Intellectual Property\n${data.intellectual_property}\n\n` +
      `## 12. Legal & Regulatory\n${data.legal_regulatory}\n\n` +
      `## 13. Governance & Board Effectiveness\n${data.governance_board_effectiveness}\n\n` +
      `## 14. Capital Structure & Dilution\n${data.capital_structure_dilution}\n\n` +
      `## 15. Risk Matrix & Mitigations\n${data.risk_matrix_mitigations}\n\n` +
      `## 16. Gaps, Uncertainties & Disclaimers\n${data.gaps_uncertainties_disclaimers}\n\n` +
      `## 17. Scenario Analysis\n${data.scenario_analysis}\n\n` +
      `## 18. Strategic Options\n${data.strategic_options}\n\n` +
      `## 19. Recommendations & Next Steps\n${data.recommendations_next_steps}\n\n` +
      `## 20. Source Map & Integrity Log\n${data.source_map_integrity_log}\n\n` +
      `---\n*This comprehensive due diligence report was automatically generated by the DD Analysis System*`;

    pdfReports.push({
      json: {
        id: data.id,
        kanboard_task_id: data.kanboard_task_id,
        company_name: data.company_name,
        pdf_content: pdfContent,
        filename: `DD_Report_${data.company_name.replace(/[^a-zA-Z0-9]/g, '_')}_${new Date().toISOString().split('T')[0]}.pdf`
      }
    });

    console.log(`📄 Generated PDF content for ${data.company_name}`);
  }
}

if (pdfReports.length === 0) {
  return [{ json: { message: 'No reports ready for PDF generation' } }];
}

return pdfReports;
